"""决战舰队 / 技能 OCR 识别模块。

提供：
- 战备舰队购买页：分数、5 张卡的费用与舰名（含不可负担卡）；
- 技能面板：左下角 ``Lv.x(y/10)`` 等级、地图页「当前拥有 N」余额；
- 买经验按钮灰态（像素取色，不做 OCR 满级判定）。

这些函数由 :class:`DecisiveMapController` 委托调用。
"""

from __future__ import annotations

import re
from typing import TYPE_CHECKING

import cv2
import numpy as np

from autowsgr.infra.logger import get_logger
from autowsgr.types import FleetSelection
from autowsgr.ui.decisive.overlay import (
    BUY_EXP_PROBE,
    COST_AREA,
    FLEET_CARD_CLICK_Y,
    FLEET_CARD_X_POSITIONS,
    MAP_SCORE_AREA,
    RESOURCE_AREA,
    RESOURCE_AREA_TIGHT,
    RESOURCE_AREA_WIDE,
    SHIP_NAME_X_RANGES,
    SHIP_NAME_Y_RANGE,
    SKILL_LEVEL_AREA,
)
from autowsgr.vision import ROI, Color, OCREngine, PixelChecker


if TYPE_CHECKING:
    import numpy as np


_log = get_logger('ui.decisive')

_LEVEL_PATTERN = re.compile(r'Lv\.?\s*(\d+)', re.IGNORECASE)


def _parse_offer_cost_text(text: str) -> int | None:
    """解析整行费用文本，兼容 x4 / X4 格式。"""
    cleaned = text.strip().replace(' ', '').lstrip('xX')
    if not cleaned:
        return None
    try:
        return int(cleaned)
    except ValueError:
        return None


def _parse_card_cost_text(text: str) -> int | None:
    """解析单卡费用。

    EasyOCR 常把左侧黄色硬币图标读成前导 ``8``（如 ``x2`` → ``82``）。
    费用本身是 1-99 的整数，去掉这个前导 ``8`` 即可还原。
    """
    cleaned = text.strip().replace(' ', '')
    cleaned = cleaned.lstrip('xX')
    if not cleaned:
        return None
    if len(cleaned) > 1 and cleaned[0] == '8':
        cleaned = cleaned[1:]
    if not cleaned.isdigit():
        return None
    value = int(cleaned)
    return value if 1 <= value <= 99 else None


def parse_skill_level(text: str) -> int | None:
    """从 ``Lv.3(0/10)`` / ``Lv.10`` 中解析技能等级。"""
    if not text:
        return None
    match = _LEVEL_PATTERN.search(text)
    if match is None:
        # 有些 OCR 结果会丢掉 Lv. 前缀，只剩 "3(0/10)"。
        match = re.search(r'(\d+)\s*[（(]', text)
    if match is None:
        return None
    value = int(match.group(1))
    return value if 0 <= value <= 99 else None


def _prepare_text_roi(image: np.ndarray, *, scale: int = 4) -> np.ndarray:
    """对小块文字区域做放大 + 提升对比度，改善 EasyOCR 无结果问题。"""
    if image.size == 0:
        return image

    gray = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
    gray = cv2.resize(gray, None, fx=scale, fy=scale, interpolation=cv2.INTER_CUBIC)
    gray = cv2.GaussianBlur(gray, (3, 3), 0)
    norm = cv2.normalize(gray, None, 0, 255, cv2.NORM_MINMAX)
    binary = cv2.threshold(norm, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[1]
    return cv2.cvtColor(binary, cv2.COLOR_GRAY2RGB)


def _roi_from_area(
    area: tuple[tuple[float, float], tuple[float, float]]
    | tuple[float, float, float, float],
) -> ROI:
    """把旧版 ``((x1,y1),(x2,y2))`` 或四元组统一归一化为 ROI。

    旧常量里存在 ``y1 > y2`` 的写法（如费用行、右上角资源），必须先
    取 min/max，否则 ROI 校验会直接抛错。
    """
    if len(area) == 2:
        (ax1, ay1), (ax2, ay2) = area
    else:
        ax1, ay1, ax2, ay2 = area
    return ROI(
        x1=min(ax1, ax2),
        y1=min(ay1, ay2),
        x2=max(ax1, ax2),
        y2=max(ay1, ay2),
    )


def _tight_text_crop(image: np.ndarray) -> np.ndarray:
    """裁掉文字周围大片空白，提升单个数字的 OCR 命中率。"""
    if image.size == 0:
        return image
    gray = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
    _, mask = cv2.threshold(gray, 110, 255, cv2.THRESH_BINARY)
    points = cv2.findNonZero(mask)
    if points is None:
        return image
    x, y, width, height = cv2.boundingRect(points)
    pad = 3
    return image[
        max(0, y - pad) : min(image.shape[0], y + height + pad),
        max(0, x - pad) : min(image.shape[1], x + width + pad),
    ]


def read_score(
    ocr: OCREngine,
    screen: np.ndarray,
    *,
    map_page: bool = False,
) -> int | None:
    """读取余额。

    ``map_page=False`` 读战备舰队购买页右上角；``map_page=True`` 读地图页
    左下角「当前拥有 N」。单张 ROI 在 33 像素高的数字上容易漏识别，
    因此依次尝试紧裁、原区域、宽区域，并各做原图/二值化两次 OCR。
    """
    areas = (
        [MAP_SCORE_AREA]
        if map_page
        else [RESOURCE_AREA_TIGHT, RESOURCE_AREA, RESOURCE_AREA_WIDE]
    )
    for area in areas:
        crop = _roi_from_area(area).crop(screen)
        if crop.size == 0:
            continue
        tight = _tight_text_crop(crop)
        candidates = [crop]
        if tight is not crop and tight.size:
            candidates.insert(0, tight)
        for image in candidates:
            prepared = _prepare_text_roi(image)
            value = ocr.recognize_number(prepared)
            if value is None:
                value = ocr.recognize_number(image)
            if value is not None:
                _log.debug('[舰队OCR] 余额: {} (map_page={})', value, map_page)
                return value
    return None


def read_skill_level(ocr: OCREngine, screen: np.ndarray) -> int | None:
    """读取左下角副官技能等级。"""
    crop = _roi_from_area(SKILL_LEVEL_AREA).crop(screen)
    result = ocr.recognize_single(crop, allowlist='0123456789Lv.()/')
    level = parse_skill_level(result.text)
    if level is None:
        prepared = _prepare_text_roi(crop)
        level = parse_skill_level(ocr.recognize_single(prepared, allowlist='0123456789Lv.()/').text)
    if level is not None:
        _log.debug('[舰队OCR] 技能等级: Lv.{}', level)
    return level


def is_buy_exp_disabled(
    screen: np.ndarray,
    *,
    disabled_color: tuple[int, int, int] | None = None,
) -> bool:
    """判断「购买经验值」按钮是否满级变灰。

    只有显式配置灰态颜色时才用像素判灰；默认不拦截。左下角按钮
    本身是深蓝底，旧版“必须接近亮蓝”的启发式会把可用按钮误判为
    满级，导致 3 级时买经验 clicks=0。满级优先由 OCR 等级判断；
    按钮不响应时由买经验循环的无进展保护停止。
    """
    if disabled_color is None:
        return False
    actual = PixelChecker.get_pixel(screen, *BUY_EXP_PROBE)
    return actual.near(Color.of(*disabled_color), 60.0)


def _recognize_row_costs(ocr: OCREngine, screen: np.ndarray) -> list[int | None]:
    """优先整行识别费用（快）；数量不足 5 时由调用方逐卡兜底。"""
    cost_roi = _roi_from_area(COST_AREA)
    results = ocr.recognize(cost_roi.crop(screen), allowlist='0123456789xX')
    results.sort(key=lambda item: item.bbox[0])
    return [_parse_offer_cost_text(result.text) for result in results]


def _recognize_card_costs(ocr: OCREngine, screen: np.ndarray) -> list[int | None]:
    """逐卡费用识别（慢但抗分辨率变化，保留 5 张卡索引对齐）。"""
    costs: list[int | None] = []
    for card_x in FLEET_CARD_X_POSITIONS:
        cost_roi = ROI(
            x1=card_x - 0.06,
            y1=0.755,
            x2=card_x + 0.035,
            y2=0.815,
        )
        result = ocr.recognize_single(
            _prepare_text_roi(cost_roi.crop(screen)),
            allowlist='0123456789xX',
        )
        cost = _parse_card_cost_text(result.text)
        if cost is None:
            raw = ocr.recognize_single(cost_roi.crop(screen), allowlist='0123456789xX')
            cost = _parse_card_cost_text(raw.text)
        costs.append(cost)
    return costs


def recognize_fleet_options(
    ocr: OCREngine,
    screen: np.ndarray,
    fallback_score: int | None = None,
    *,
    score_status: list[bool] | None = None,
) -> tuple[int, dict[str, FleetSelection]]:
    """OCR 识别战备舰队获取界面的全部 5 张卡。

    与旧实现不同：即使某张卡费用高于当前余额，也识别其名称与费用，
    由纯逻辑层 ``choose_purchases()`` 统一拦截，避免“卡面变灰”漏判。
    """
    _log.debug('[舰队OCR] 开始识别战备舰队可选项')

    score = read_score(ocr, screen)
    score_ok = score is not None
    if score_status is not None:
        score_status.append(score_ok)
    if score is None:
        score = fallback_score if fallback_score is not None else 0
        _log.warning('[舰队OCR] 分数 OCR 失败，保守回退: {}', score)

    # 整行 OCR 快；数量或解析不足时逐卡兜底。
    costs = _recognize_row_costs(ocr, screen)
    if len(costs) < len(SHIP_NAME_X_RANGES) or any(cost is None for cost in costs):
        _log.debug('[舰队OCR] 整行费用不完整 ({})，逐卡兜底', costs)
        costs = _recognize_card_costs(ocr, screen)
    _log.debug('[舰队OCR] 识别到费用: {}', costs)

    selections: dict[str, FleetSelection] = {}
    for index, cost in enumerate(costs[: len(SHIP_NAME_X_RANGES)]):
        if cost is None:
            continue
        x_range = SHIP_NAME_X_RANGES[index]
        y_range = SHIP_NAME_Y_RANGE
        name_roi = ROI(x1=x_range[0], y1=y_range[0], x2=x_range[1], y2=y_range[1])
        name_img = name_roi.crop(screen)

        name = ocr.recognize_ship_name(name_img)
        if name is None:
            raw = ocr.recognize_single(name_img)
            name = raw.text.strip() or f'未识别_{index}'
            _log.debug("[舰队OCR] 舰船名模糊匹配失败, 原文: '{}'", name)

        click_x = FLEET_CARD_X_POSITIONS[index]
        selections[name] = FleetSelection(
            name=name,
            cost=cost,
            click_position=(click_x, FLEET_CARD_CLICK_Y),
        )

    _log.info('[舰队OCR] 舰队选项: {}', {k: v.cost for k, v in selections.items()})
    return score, selections
